// Release notes for the public Updates page.
//
// This is the ONE documented exception to "all copy lives in messages/": the
// arrays below are copied verbatim from the desktop app repo
// (src/data/changelog.ts in the PDRKalk app) so the site and the in-app
// "Was ist neu?" modal never drift. A release bump is ONE entry here:
// lib/site.ts derives APP_VERSION (newest status 'public') and TEST_VERSION
// (newest status 'testing', or null), and the download URLs, JSON-LD
// softwareVersion and every "Version {version}" string follow from that.

export type ReleaseStatus = 'public' | 'testing';

export type Release = {
  id: string;
  date: string;
  version: string;
  status: ReleaseStatus;
  /** German items (canonical). Prefixes Neu:/Verbessert:/Fix: drive grouping. */
  items: string[];
  itemsEn?: string[];
  itemsFr?: string[];
  itemsIt?: string[];
};

